def recursive_factorial(n: int) -> Union[int, str]:
    """
    Computes the factorial of a non-negative integer n using recursion.

    Parameters:
    n (int): The number for which the factorial is to be calculated.

    Returns:
    Union[int, str]: The factorial of n if n is non-negative, otherwise a message indicating that factorial is not defined for negative numbers.
