import string

def count_words(input_string: str) -> dict:
    """
    Counts the frequency of each word in a given string, ignoring case and punctuation.

    :param input_string: The string to process.
    :return: A dictionary with words as keys and their frequencies as values.
    """
    cleaned_string = input_string.translate(str.maketrans('', '', string.punctuation)).lower()
    words = cleaned_string.split()
    word_count = {}
    for word in words:
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1
    return word_count

