def boyer_moore_search(T, P):
    """
    Implement the Boyer-Moore string search algorithm to find the lowest index
    in T where the substring P begins. If P is not found in T, return -1.

    :param T: The text string.
    :param P: The pattern string.
    :return: The lowest index in T where P begins, or -1 if P is not found.
    """
    def preprocess(pattern):
        """Create a 'last' dictionary for the pattern with the modified rule."""
        last = {}
        for k in range(len(pattern) - 1, -1, -1):
            if pattern[k] not in last:
                last[pattern[k]] = k
        return last

    last = preprocess(P)
    i = len(P) - 1
    k = len(P) - 1

    while i < len(T):
        if T[i] == P[k]:
            if k == 0:
                return i
            else:
                i -= 1
                k -= 1
        else:
            j = last.get(T[i], -1)
            offset = max(1, k - j)
            i += offset
            k = len(P) - 1

    return -1

