def is_prime_lucas(n):
    """
    Determines if a given number n is prime using a modified Lucas primality test.

    Parameters:
    n (int): The number to check for primality.

    Returns:
    bool: True if n is prime, False otherwise.
    """
    if n < 2:
        return False

    def lucas(n):
        """
        Computes the nth Lucas number.

        Parameters:
        n (int): The index of the Lucas number to compute.

        Returns:
        int: The nth Lucas number.
        """
        if n == 0:
            return 2
        elif n == 1:
            return 1
        else:
            a, b = 2, 1
            for _ in range(2, n + 1):
                a, b = b, a + b
            return b

    if n == 2:
        return True
    if n % 2 == 0:
        return False

    if lucas(n - 1) % n == 0:
        return True

    for i in range(3, int(n ** 0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

