def find_max_min(numbers):
    """
    Returns a tuple containing the maximum and minimum values from the list.
    If the list is empty or contains non-numeric values, returns None.

    :param numbers: List of numbers (integers and/or floats)
    :return: Tuple (max_val, min_val) or None
    """
    if not isinstance(numbers, list) or not numbers:
        return None

    try:
        max_val = float('-inf')
        min_val = float('inf')
        for num in numbers:
            if not isinstance(num, (int, float)):
                raise ValueError("List contains non-numeric values.")
            if num > max_val:
                max_val = num
            if num < min_val:
                min_val = num
        return (max_val, min_val)
    except ValueError:
        return None

