def rotate_list(input_list, n):
    """
    Rotates the elements of a list to the right by n positions if n is positive,
    or to the left by n positions if n is negative.

    Args:
    input_list (list): The list of elements to be rotated.
    n (int): The number of positions to rotate the list.

    Returns:
    list or None: The rotated list, or None if an error occurs.
    """
    try:
        if not isinstance(input_list, list):
            raise TypeError("The first argument must be a list.")
        if not isinstance(n, int):
            raise TypeError("The second argument must be an integer.")
        if not input_list or n == 0:
            return input_list
        n = n % len(input_list)
        if n < 0:
            n += len(input_list)
        return input_list[-n:] + input_list[:-n]
    except Exception:
        return None

