def merge_dicts(dict1, dict2):
    """
    Merges two dictionaries into one. If there are overlapping keys, the values are combined into a list.
    If the values are already lists, they are extended.

    :param dict1: First dictionary with keys as strings and values as integers or lists of integers.
    :param dict2: Second dictionary with keys as strings and values as integers or lists of integers.
    :return: Merged dictionary with combined values.
    """
    merged_dict = dict1.copy()

    for key, value in dict2.items():
        if key in merged_dict:
            if isinstance(merged_dict[key], list) and isinstance(value, list):
                merged_dict[key] = merged_dict[key] + value
            elif isinstance(merged_dict[key], list):
                merged_dict[key].append(value)
            elif isinstance(value, list):
                merged_dict[key] = [merged_dict[key]] + value
            else:
                merged_dict[key] = [merged_dict[key], value]
        else:
            merged_dict[key] = value

    return merged_dict

