def circularSearch(target, numbers):
    """
    Finds the index of the target in a circularly sorted array of integers.

    :param target: Integer to search for in the array.
    :param numbers: List of integers representing the circularly sorted array.
    :return: Index of the target if found, otherwise -1.
    """
    def find_pivot(arr):
        """
        Finds the index of the smallest element in the circularly sorted array.

        :param arr: List of integers representing the circularly sorted array.
        :return: Index of the smallest element.
        """
        low, high = 0, len(arr) - 1
        while low < high:
            mid = (low + high) // 2
            if arr[mid] > arr[high]:
                low = mid + 1
            else:
                high = mid
        return low

    def binary_search(arr, low, high, target):
        """
        Performs binary search on a subarray of the circularly sorted array.

        :param arr: List of integers representing the circularly sorted array.
        :param low: Starting index of the subarray.
        :param high: Ending index of the subarray.
        :param target: Integer to search for in the subarray.
        :return: Index of the target if found, otherwise -1.
        """
        while low <= high:
            mid = (low + high) // 2
            if arr[mid] == target:
                return mid
            elif arr[mid] < target:
                low = mid + 1
            else:
                high = mid - 1
        return -1

    n = len(numbers)
    if n == 0:
        return -1

    pivot = find_pivot(numbers)

    if numbers[pivot] == target:
        return pivot
    elif target <= numbers[n - 1]:
        return binary_search(numbers, pivot, n - 1, target)
    else:
        return binary_search(numbers, 0, pivot - 1, target)

