def quick_select_largest(numbers: List[int], k: int) -> int:
    """
    Finds the kth largest element in an unsorted list of integers using a method similar to quick sort.

    :param numbers: List of integers.
    :param k: The kth position to find the largest element for (1-based index).
    :return: The kth largest element in the list.
    """
    def partition(low: int, high: int) -> int:
        pivot_index = high
        pivot_value = numbers[pivot_index]
        i = low
        for j in range(low, high):
            if numbers[j] > pivot_value:
                numbers[i], numbers[j] = numbers[j], numbers[i]
                i += 1
        numbers[i], numbers[pivot_index] = numbers[pivot_index], numbers[i]
        return i

