    """
    Determines if the input string s containing only '(', ')', '{', '}', '[' and ']' is valid.
    A string is valid if every opening bracket has a corresponding closing bracket of the same type
    and opening brackets are closed in the correct order.

    :param s: The input string consisting of brackets.
    :return: True if the string is valid, False otherwise.
    """
    matching_bracket = {')': '(', '}': '{', ']': '['}
    stack = []

