    Finds the smallest missing positive integer in the list.

    :param nums: List of integers which may contain duplicates and negative numbers.
    :return: The smallest missing positive integer.
    """
    n = len(nums)

    # Step 1: Segregate positive numbers from non-positive numbers.
    j = 0
    for i in range(n):
        if nums[i] <= 0:
            nums[i], nums[j] = nums[j], nums[i]
            j += 1

    # Step 2: Use the index as a hash to record the presence of numbers.
    for i in range(j, n):
        val = abs(nums[i])
        if j <= val <= n - j:
            if nums[val - 1 + j] > 0:
                nums[val - 1 + j] = -nums[val - 1 + j]

    # Step 3: Find the first index where the value is positive.
    for i in range(j, n):
        if nums[i] > 0:
            return i - j + 1

    return n - j + 1

