def fibonacci_sequence(n, memo={}):
    """
    Generate the first n numbers in the Fibonacci sequence using recursion with memoization.

    :param n: The number of Fibonacci numbers to generate.
    :param memo: A dictionary to store previously computed Fibonacci numbers.
    :return: A list containing the first n Fibonacci numbers.
    """
    if n <= 0:
        return []
    elif n == 1:
        return [0]
    elif n == 2:
        return [0, 1]

    if 0 not in memo:
        memo[0] = 0
    if 1 not in memo:
        memo[1] = 1

    def fib_memo(k):
        if k not in memo:
