def create_pairs(image_files, annotation_files):
    """
    Creates pairs of image and annotation files based on their base names.

    Args:
    image_files (list of str): List of image file paths.
    annotation_files (list of str): List of annotation file paths.

    Returns:
    list of tuples: Each tuple contains an image file path and its corresponding annotation file path.

    Raises:
    ValueError: If the lengths of image_files and annotation_files do not match.
    ValueError: If there is a mismatch in the base names of the sorted image and annotation files.
    """
    if len(image_files) != len(annotation_files):
        raise ValueError("The lengths of image_files and annotation_files must match.")

    def extract_base_name(filename):
        import re
        match = re.match(r"(.+?)(?:_image\.png|_annotation\.txt)$", filename)
        if match:
            return match.group(1)
        else:
            raise ValueError(f"Filename '{filename}' does not match the expected format.")

    image_files.sort(key=extract_base_name)
    annotation_files.sort(key=extract_base_name)

    for img_file, ann_file in zip(image_files, annotation_files):
        if extract_base_name(img_file) != extract_base_name(ann_file):
            raise ValueError("The image and annotation files do not match.")

    return list(zip(image_files, annotation_files))

