def longest_common_subsequence(X, Y):
    """
    Computes the length of the longest common subsequence (LCS) of two strings X and Y.

    :param X: First input string
    :param Y: Second input string
    :return: Length of the longest common subsequence
    """
    m = len(X)
    n = len(Y)
    L = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                L[i][j] = 0
            elif X[i - 1] == Y[j - 1]:
