def has_cycle(graph):
    """
    Determines if a directed graph contains a cycle.

    :param graph: A dictionary representing the directed graph as an adjacency list.
    :return: True if the graph contains a cycle, False otherwise.
    """
    visited = set()
    recursion_stack = set()

    def is_cyclic(v):
        visited.add(v)
        recursion_stack.add(v)

        for neighbour in graph.get(v, []):
            if neighbour in recursion_stack:
                return True
            if neighbour not in visited:
                if is_cyclic(neighbour):
                    return True

        recursion_stack.remove(v)
        return False

    for node in graph:
        if node not in visited:
            if is_cyclic(node):
                return True
    return False

