def find_pairs(arr, k):
    """
    Finds the number of unique pairs (arr[i], arr[j]) in the array such that
    the absolute difference between arr[i] and arr[j] is exactly k.

    :param arr: List[int] - The list of integers.
    :param k: int - The target absolute difference.
    :return: int - The number of unique pairs with the specified absolute difference.
    """
    pairs = set()
    for i in range(len(arr)):
        for j in range(i + 1, len(arr)):
            if abs(arr[i] - arr[j]) == k:
                pairs.add((min(arr[i], arr[j]), max(arr[i], arr[j])))
    return len(pairs)

