def find_smallest_missing_positive_integer(numbers):
    """
    Finds the smallest positive integer that does not appear in the given list of integers.

    :param numbers: List[int] - A list of integers.
    :return: int - The smallest missing positive integer.
    """
    n = len(numbers)

    for i in range(n):
        while 1 <= numbers[i] <= n and numbers[numbers[i] - 1] != numbers[i]:
            correct_index = numbers[i] - 1
            numbers[i], numbers[correct_index] = numbers[correct_index], numbers[i]

    for i in range(n):
        if numbers[i] != i + 1:
            return i + 1

    return n + 1

