    """
    Processes a string by escaping specific characters if the escape flag is True.

    Parameters:
    val (str): The input string to be processed.
    escape (bool): A flag indicating whether to apply escape sequences (default is False).

    Returns:
    str: The processed string with escape sequences applied if escape is True, otherwise the original string.
    """
    if not escape:
        return val

    escape_chars = {
        "'": "\\'",
        '"': '\\"',
        '\\': '\\\\',
        'n': '\n'
    }

    result = []

    for char in val:
