    """Generates a paginated response from a list of items.

    Args:
        items (list): List of items to paginate.
        cursor (int, optional): Cursor to start pagination from (integer offset). Defaults to None.
        limit (int, optional): Maximum number of items to return per page. Defaults to 10.

    Returns:
        dict: Dictionary with paginated items and pagination info.

    Raises:
        ValueError: If items is not a list, limit is not a positive integer, or cursor is not an integer or None.
        ValueError: If the total count of items is negative.
    """
    import math

    if not isinstance(items, list):
        raise ValueError("Items must be a list.")
    if limit <= 0:
        raise ValueError("Limit must be a positive integer.")
    if cursor is not None and not isinstance(cursor, int):
        raise ValueError("Cursor must be an integer or None.")
    if len(items) < 0:
        raise ValueError("Total count of items cannot be negative.")

    total_count = len(items)
    if total_count == 0:
