    """
    Finds the number in the sorted list that is closest to the target number.
    If the list is empty, returns None. If two numbers are equally close, returns the smaller number.

    :param sorted_list: List[int] - A sorted list of integers.
    :param target: int - The target integer.
    :return: int or None - The closest integer in the list or None if the list is empty.
    """
    if not sorted_list:
        return None

    left, right = 0, len(sorted_list) - 1

    if target < sorted_list[left]:
        return sorted_list[left]

    if target > sorted_list[right]:
        return sorted_list[right]

    while left < right:
        mid = (left + right) // 2

        if sorted_list[mid] == target:
            return sorted_list[mid]

        if abs(sorted_list[mid] - target) <= abs(sorted_list[mid + 1] - target):
            right = mid
        else:
            left = mid + 1

    return sorted_list[left]

