    """
    Returns the length of the longest palindromic subsequence in the given string s.

    :param s: A string consisting of lowercase English letters.
    :return: An integer representing the length of the longest palindromic subsequence.
    """
    def lps_recursive(start: int, end: int, memo) -> int:
        if start > end:
            return 0
        if start == end:
            return 1
        if (start, end) in memo:
            return memo[(start, end)]

        if s[start] == s[end]:
            memo[(start, end)] = 2 + lps_recursive(start + 1, end - 1, memo)
        else:
            memo[(start, end)] = max(lps_recursive(start + 1, end, memo), lps_recursive(start, end - 1, memo))

        return memo[(start, end)]

    memo = {}
    return lps_recursive(0, len(s) - 1, memo)

