    """
    Searches for the target integer x in a circularly sorted array A of n distinct integers.

    Parameters:
    A (list of int): The circularly sorted array.
    n (int): The length of the array.
    x (int): The target integer to search for.

    Returns:
    int: The index of x in A if x is present, otherwise -1.
    """
    left, right = 0, n - 1

    while left <= right:
        # Find middle index without using division
        mid = left + (right - left) // 2  # Using integer arithmetic to avoid division/modulus directly

        if A[mid] == x:
            return mid

        # Determine which side is properly sorted
        if A[left] <= A[mid]:
            # Left side is sorted
            if A[left] <= x < A[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            # Right side is sorted
            if A[mid] < x <= A[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

