    """
    Generate the Fibonacci sequence up to a specified number of terms using memoization.

    :param n_terms: An integer representing the number of terms in the sequence to generate.
    :return: A list containing the Fibonacci sequence up to the specified number of terms.
    """
    memo = {0: 0, 1: 1}

