def evaluate_postfix(expression: str) -> float:
    """
    Evaluates a postfix expression given as a string of space-separated tokens.

    :param expression: A string representing the postfix expression.
    :return: The result of the postfix expression as a floating-point number.
    """
    tokens = expression.split()
    stack = []
    operators = {
        '+': lambda a, b: a + b,
        '-': lambda a, b: a - b,
        '*': lambda a, b: a * b,
        '/': lambda a, b: a / b,
    }

    for token in tokens:
        if token in operators:
            operand2 = stack.pop()
            operand1 = stack.pop()
            result = operators[token](operand1, operand2)
            stack.append(result)
        else:
            stack.append(float(token))

    return stack.pop()

