    """
    Perform a recursive binary search to find the first occurrence of the target in the sorted array.

    :param arr: List[int] - A sorted list of integers.
    :param target: int - The target integer to search for.
    :param low: int - The starting index for the search (default is 0).
    :param high: int - The ending index for the search (default is the last index of the array).
    :return: int - The index of the first occurrence of the target, or -1 if not found.
    """
    if high is None:
        high = len(arr) - 1

    if low > high:
        return -1

    mid = low + (high - low) // 2
    if arr[mid] < target:
        return recursive_binary_search(arr, target, mid + 1, high)
    elif arr[mid] > target:
        return recursive_binary_search(arr, target, low, mid - 1)
    elif mid > 0 and arr[mid - 1] == target:
        return recursive_binary_search(arr, target, low, mid - 1)
    else:
        return mid

