def find_lis(nums):
    """
    Finds the longest increasing subsequence in a list of integers.

    :param nums: List[int] - A list of integers.
    :return: List[int] - A list representing the longest increasing subsequence.
    """
    if not nums:
        return []

    n = len(nums)
    dp = [1] * n
    prev = [-1] * n

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j] and dp[i] < dp[j] + 1:
                dp[i] = dp[j] + 1
                prev[i] = j

    max_index = 0
    for i in range(1, n):
        if dp[i] > dp[max_index]:
            max_index = i

    lis = []
    while max_index != -1:
        lis.append(nums[max_index])
        max_index = prev[max_index]

    lis.reverse()
    return lis

