def evaluate_rpn(tokens):
    """
    Evaluates a Reverse Polish Notation (RPN) expression.

    :param tokens: List of strings representing the RPN expression.
    :return: Integer result of the evaluated RPN expression.
    """
    stack = []

    for token in tokens:
        if token.isdigit() or (token[0] == '-' and token[1:].isdigit()):
            stack.append(int(token))
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(int(a / b))

    return stack[0]

