def find_fibonacci(n):
    """
    Calculate the nth Fibonacci number using a recursive approach.

    :param n: An integer representing the position in the Fibonacci sequence.
    :return: The nth Fibonacci number if n is positive, otherwise a string error message.
    """
    if n <= 0:
        return "Input should be a positive integer."
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        return find_fibonacci(n - 1) + find_fibonacci(n - 2)


