def sum_of_primes(n):
    """
    Computes the sum of all prime numbers less than a given number n.

    Parameters:
    n (int): The upper limit (exclusive) to find the sum of prime numbers.

    Returns:
    int: The sum of all prime numbers less than n.
    """
    if n <= 2:
        return 0
    sieve = [True] * n
    sieve[0] = sieve[1] = False
    for i in range(2, int(n**0.5) + 1):
        if sieve[i]:
            sieve[i*i:n:i] = [False] * ((n - i*i - 1) // i + 1)
    return sum(i for i, is_prime in enumerate(sieve) if is_prime)

